from itertools import product

def solve(n):
    # A = (a_0, a_1, ..., a_n)
    # B = (b_0, b_1, ..., b_n)
    # B is determined by A: b_i = count of i in A
    # A is determined by B: a_i = count of i in B

    # If a_i and b_i are in {0, ..., n}, we can iterate.
    results = []
    for A in product(range(n + 1), repeat=n + 1):
        if sum(A) == n + 1:
            B = [0] * (n + 1)
            for val in A:
                B[val] += 1

            if sum(B) == n + 1:
                A_prime = [0] * (n + 1)
                for val in B:
                    A_prime[val] += 1

                if A == A_prime:
                    results.append(A)
    return results

for n in range(1, 5):
    res = solve(n)
    print(f"n={n}: {res}")

