def solve(n):
    import itertools
    results = []
    # a is a sequence of n+1 integers from 0 to n
    # sum(a) must be n+1
    for a in itertools.product(range(n + 1), repeat=n + 1):
        if sum(a) != n + 1:
            continue
        b = f(a, n)
        if any(x > n for x in b):
            continue
        a_prime = f(b, n)
        if a_prime == a:
            results.append(a)
    return results

