def solve_real(n):
    import itertools
    results = []
    # Using a more efficient way to iterate since sum(a) = n+1
    # and a_i in {0, ..., n}
    # We can use a recursive generator to find all partitions of n+1 into n+1 parts
    def get_partitions(target, num_parts, max_val):
        if num_parts == 1:
            if target <= max_val:
                yield [target]
            return
        for i in range(max_val + 1):
            if i <= target:
                for p in get_partitions(target - i, num_parts - 1, max_val):
                    yield [i] + p

    for a in get_partitions(n + 1, n + 1, n):
        b = f(a, n)
        if any(x > n for x in b):
            continue
        a_prime = f(b, n)
        if a_prime == a:
            results.append((a, b))
    return results

