def solve_small_N_correct(N):
    import itertools
    def get_b(a):
        b = [0] * (N + 1)
        for x in a:
            if x <= N:
                b[x] += 1
        return b
    def get_a(b):
        a = [0] * (N + 1)
        for x in b:
            if x <= N:
                a[x] += 1
        return a
    solutions = []
    def generate_a(index, current_sum, current_a):
        if index == N + 1:
            if current_sum == N + 1:
                b = get_b(current_a)
                a_prime = get_a(b)
                if a_prime == current_a:
                    solutions.append(list(current_a))
            return
        rem_len = (N + 1) - index
        rem_sum = (N + 1) - current_sum
        for val in range(max(0, rem_sum - (rem_len - 1) * (N + 1)), min(rem_sum, N + 1) + 1):
            current_a.append(val)
            generate_a(index + 1, current_sum + val, current_a)
            current_a.pop()
    generate_a(0, 0, [])
    return solutions

