def solve():
    for n in range(1, 11):
        # a is a tuple of n integers
        # b is a tuple of n integers
        # We need sum(a) = n, sum(b) = n
        # b_k = count of k in a
        # a_k = count of k in b
        # All a_k, b_k must be in {0, ..., n}
        # But the product is over k=0...n-1, 
        # so if any a_i > n-1, the product equality fails.
        # Thus a_i must be in {0, ..., n-1}.
        # Similarly b_k must be in {0, ..., n-1}.
        # However, a_k is the count of k in b, so a_k <= n.
        # But the product is over k=0...n-1, so a_k must be 0 for k >= n.
        # Thus all a_i, b_j must be in {0, ..., n-1}.

        import itertools
        for a in itertools.product(range(n), repeat=n):
            if sum(a) != n:
                continue

            b = [0] * n
            for x in a:
                if x < n:
                    b[x] += 1

            if sum(b) != n:
                continue

            a_new = [0] * n
            for x in b:
                if x < n:
                    a_new[x] += 1

            if tuple(a_new) == a:
                print(f"n={n}: a={a}")

