def get_f(a):
    n = len(a)
    b = [0] * n
    for val in a:
        if val < n:
            b[val] += 1
    return b

def solve_small_n(N):
    solutions = []
    def find_a(idx, current_sum, current_weighted_sum, current_a):
        if idx == N + 1:
            if current_sum == N + 1 and current_weighted_sum == N + 1:
                b = get_f(current_a)
                c = get_f(b)
                if c == current_a:
                    solutions.append((current_a, b))
            return
        rem_sum = (N + 1) - current_sum
        rem_weighted = (N + 1) - current_weighted_sum
        limit = rem_sum
        if idx > 0:
            limit = min(limit, rem_weighted // idx)
        for val in range(limit + 1):
            current_a.append(val)
            find_a(idx + 1, current_sum + val, current_weighted_sum + idx * val, current_a)
            current_a.pop()
    find_a(0, 0, 0, [])
    return solutions

