def f(a):
    M = len(a)
    b = [0] * M
    for val in a:
        if val < M:
            b[val] += 1
    return b

def solve():
    for M in range(1, 21):
        good_sequences = []
        def generate_partitions(target, max_val, current_partition):
            if target == 0:
                a = [0] * M
                sum_ai = 0
                for p in current_partition:
                    a[p] += 1
                    sum_ai += 1
                if sum_ai <= M:
                    a[0] = M - sum_ai
                    b = f(a)
                    c = f(b)
                    if c == a:
                        good_sequences.append(a)
                return
            for i in range(1, min(target, max_val) + 1):
                current_partition.append(i)
                generate_partitions(target - i, i, current_partition)
                current_partition.pop()

        generate_partitions(M, M - 1, [])

        unique_good_sequences = []
        seen = set()
        for seq in good_sequences:
            t = tuple(seq)
            if t not in seen:
                unique_good_sequences.append(seq)
                seen.add(t)

        sums = []
        for seq in unique_good_sequences:
            S = sum((i + 1) * (seq[i]**2) for i in range(M))
            sums.append(S)

        print(f"M={M}: {sums} sequences: {[tuple(s) for s in unique_good_sequences]}")

solve()

